<?php
require_once 'config/config.php';require_once 'includes/functions.php';require_login();verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $act=$_POST['action']??'';
 if($act==='save'){$id=(int)($_POST['id']??0);$code=trim($_POST['member_code']??'');$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$status=$_POST['status']??'Active';
 if($code===''||$name===''){flash('Member code and name are required.','error');redirect('members.php');}
 try{if($id){$s=$pdo->prepare('UPDATE members SET member_code=?,name=?,email=?,phone=?,address=?,status=? WHERE id=?');$s->execute([$code,$name,$email,$phone,$address,$status,$id]);}
 else{$s=$pdo->prepare('INSERT INTO members(member_code,name,email,phone,address,joined_on,status) VALUES(?,?,?,?,?,CURDATE(),?)');$s->execute([$code,$name,$email,$phone,$address,$status]);}flash('Member saved successfully.');}
 catch(PDOException $e){flash('Could not save member. Member code may already exist.','error');}redirect('members.php');}
 if($act==='delete'){$id=(int)$_POST['id'];$s=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE member_id=? AND status='Issued'");$s->execute([$id]);if($s->fetchColumn())flash('Member has an active book issue and cannot be deleted.','error');else{try{$pdo->prepare('DELETE FROM members WHERE id=?')->execute([$id]);flash('Member deleted.');}catch(PDOException $e){flash('Member has transaction history and cannot be deleted.','error');}}redirect('members.php');}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM members WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$q=trim($_GET['q']??'');$sql='SELECT m.*, (SELECT COUNT(*) FROM loans l WHERE l.member_id=m.id AND l.status="Issued") active_loans FROM members m';$args=[];if($q!==''){$sql.=' WHERE m.name LIKE ? OR m.member_code LIKE ? OR m.phone LIKE ?';$args=["%$q%","%$q%","%$q%"];} $sql.=' ORDER BY m.id DESC';$s=$pdo->prepare($sql);$s->execute($args);$members=$s->fetchAll();
$page_title='Members';require 'includes/header.php';?>
<div class="page-heading"><div><p class="eyebrow">READERS</p><h1>Library members</h1><p class="muted">Register members and manage their account status.</p></div></div>
<div class="content-grid"><section class="panel form-panel"><h2><?=$edit?'Edit member':'Register member'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid">
<div class="field"><label>Member code *</label><input name="member_code" required placeholder="LIB-1003" value="<?=e($edit['member_code']??'')?>"></div><div class="field"><label>Full name *</label><input name="name" required value="<?=e($edit['name']??'')?>"></div>
<div class="field"><label>Email</label><input type="email" name="email" value="<?=e($edit['email']??'')?>"></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($edit['phone']??'')?>"></div>
<div class="field full"><label>Address</label><textarea name="address" rows="2"><?=e($edit['address']??'')?></textarea></div><div class="field"><label>Status</label><select name="status"><option <?=($edit['status']??'Active')==='Active'?'selected':''?>>Active</option><option <?=($edit['status']??'')==='Inactive'?'selected':''?>>Inactive</option></select></div></div><button class="btn primary">Save member</button><?php if($edit):?> <a class="btn light" href="members.php">Cancel</a><?php endif;?></form></section>
<section class="panel"><div class="panel-heading"><h2>Member directory <span class="count"><?=count($members)?></span></h2><form class="search-form"><input name="q" value="<?=e($q)?>" placeholder="Search name, code, phone"><button class="btn dark">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Contact</th><th>Joined</th><th>Active loans</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($members as $m):?><tr><td><b><?=e($m['name'])?></b><small><?=e($m['member_code'])?></small></td><td><?=e($m['phone']?:'—')?><small><?=e($m['email']?:'')?></small></td><td><?=e($m['joined_on'])?></td><td><?=$m['active_loans']?></td><td><span class="pill <?=$m['status']==='Active'?'green':'gray'?>"><?=e($m['status'])?></span></td><td class="actions"><a href="members.php?edit=<?=$m['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this member?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="link danger-link">Delete</button></form></td></tr><?php endforeach;?><?php if(!$members):?><tr><td colspan="6" class="empty">No members found.</td></tr><?php endif;?></tbody></table></div></section></div>
<?php require 'includes/footer.php';?>
